/* Guest gifts. Management secrets stay in this browser or a private fragment link. */
(() => {
 'use strict';
 let config={configured:false,guestMode:false,checkoutEnabled:false},dialog=null,view='manage',shopCategory='flower',poll=null;
 const recordsKey='doll-heart:guest-gifts:v1',pendingKey='doll-heart:guest-pending:v1',memory=new Map();
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=p=>new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:0}).format(p.amountMinor/100);
 const date=value=>value?new Date(value).toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}):'ยังไม่เริ่มนับ';
 async function api(path,{method='GET',body}={}){let response;try{response=await fetch('/api/'+path,{method,credentials:path==='gifts/read'?'omit':'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});}catch{throw new Error('เชื่อมต่อระบบไม่ได้ ลองใหม่อีกครั้งนะ');}let data;try{data=await response.json();}catch{throw new Error('ระบบยังไม่พร้อม ลองใหม่อีกครั้งนะ');}if(!response.ok){const e=new Error(data.message||'ทำรายการไม่สำเร็จ');e.code=data.error;throw e;}return data;}
 const notify=()=>window.dispatchEvent(new Event('cloud-ready'));
 const ready=window.LoveRoute?.isRecipient()?Promise.resolve():(async()=>{try{config=await api('config');}catch{}notify();})();
 const has=()=>true;
 function records(){try{const rows=JSON.parse(localStorage.getItem(recordsKey)||'[]');if(Array.isArray(rows))for(const row of rows)if(row?.id&&row?.manageToken)memory.set(row.id,row);}catch{}return [...memory.values()].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));}
 function remember(row){records();memory.set(row.id,{...memory.get(row.id),...row});try{localStorage.setItem(recordsKey,JSON.stringify([...memory.values()].slice(-200)));return true;}catch{return false;}}
 const manageUrl=row=>location.origin+'/manage#'+new URLSearchParams({id:row.id,key:row.manageToken});
 function shell(title,body){dialog.innerHTML=`<header class="cloud-header"><div><span class="eyebrow">OUR LITTLE LOVE STUDIO</span><h2 id="cloud-title">${title}</h2></div><button class="paint-close" data-cloud-close aria-label="ปิดหน้าจัดการ">×</button></header><div class="cloud-body">${body}<p id="cloud-status" role="status"></p></div>`;}
 function error(message){const el=dialog?.querySelector('#cloud-status');if(el)el.textContent=message;}
 function copyField(label,value,kind){return `<label class="guest-link-label" for="guest-${kind}">${label}</label><div class="link-box"><input id="guest-${kind}" readonly value="${esc(value)}"><button data-guest-copy="${kind}" type="button">คัดลอก</button></div>`;}
 const sceneCanvas=p=>`<canvas class="shop-scene" width="640" height="560" data-shop-scene="${esc(p.asset)}" role="img" aria-label="ฉากจริง ${esc(p.name)}"></canvas>`;
 function paintShopArt(){
  dialog.querySelectorAll('[data-shop-scene]').forEach(c=>window.PixelLove.scene(c.getContext('2d'),c.dataset.shopScene,c.width,c.height));
  dialog.querySelectorAll('[data-scene-doll]').forEach(c=>window.PixelLove.draw(c,window.DollHeart?.getState()||window.GiftSchema.defaults()));
  dialog.querySelectorAll('[data-shop-flower]').forEach(c=>{const f=window.PixelLove.flowers.find(f=>f.id===c.dataset.shopFlower);window.PixelLove.flowerIcon(c,f);});
  dialog.querySelectorAll('[data-shop-animal]').forEach(c=>{const a=window.PixelLove.animals.find(a=>a.id===c.dataset.shopAnimal);window.PixelLove.draw(c,{...window.GiftSchema.defaults(),animal:a.id,bodyColor:a.color,outfit:'none',hat:'none',glasses:'none',flowers:[]});});
 }
 function renderShop(){
  const all=config.products||window.LoveCatalog.products;if(!all.some(p=>p.type===shopCategory))shopCategory=all[0]?.type||'flower';const names={flower:'ดอกไม้',animal:'ตุ๊กตา',background:'ฉาก'};
  shell('ร้านเล็ก ๆ ของคนมีความรัก',`<div class="shop-trial-banner"><span>♡</span><div><strong>เลือกลองก่อน จ่ายครั้งเดียวตอนส่ง</strong><p>ใช้กับของขวัญนี้หนึ่งชิ้น · ซื้อของพิเศษรวมลิงก์ 30 วัน ไม่บวกเพิ่ม 19 บาท</p></div></div><div class="shop-categories" role="group" aria-label="หมวดสินค้า">${Object.entries(names).map(([type,name])=>`<button data-shop-category="${type}" aria-pressed="${shopCategory===type}">${name}<span>${all.filter(p=>p.type===type).length}</span></button>`).join('')}</div><div class="shop-grid ${shopCategory==='background'?'shop-grid-scenes':''}">${all.filter(p=>p.type===shopCategory).map(p=>`<article class="shop-card"><div class="shop-art ${p.type==='background'?'shop-art-scene':''}">${p.type==='animal'?`<canvas class="shop-animal" width="200" height="216" data-shop-animal="${p.asset}" aria-hidden="true"></canvas>`:p.type==='flower'?`<canvas width="96" height="96" data-shop-flower="${p.asset}" aria-hidden="true"></canvas>`:`<button class="scene-preview-trigger" data-preview-scene="${p.id}" aria-label="ดูฉากเต็ม ${esc(p.name)}">${sceneCanvas(p)}<span>ดูฉากเต็ม</span></button>`}</div>${p.type!=='background'?`<span class="special-label">${p.type==='animal'?'Special doll':'Special flower'}</span>`:''}<h3>${esc(p.name)}</h3><p>${esc(p.note)}</p><div class="shop-price"><strong>${money(p)}</strong><span>ต่อของขวัญ 1 ชิ้น · รวม 30 วัน</span></div><button class="secondary-button wide" data-select-product="${p.id}">เลือกลองในของขวัญ</button></article>`).join('')}</div><p class="helper">ยังไม่หักเงินเมื่อกดเลือก · ของพื้นฐานส่งฟรี 1 ชั่วโมง · <a href="/purchase-policy.html" target="_blank" rel="noopener">รายละเอียดการซื้อ</a></p>`);paintShopArt();
 }
 function previewScene(id){const p=(config.products||window.LoveCatalog.products).find(p=>p.id===id);if(!p)return;shell(esc(p.name),`<section class="scene-inspector"><p>ภาพฉากจริง · ${money(p)} ต่อของขวัญ รวมลิงก์ 30 วัน</p><div class="scene-inspector-stage">${sceneCanvas(p)}<canvas class="scene-inspector-doll hidden" width="200" height="216" data-scene-doll aria-hidden="true"></canvas></div><div class="scene-mode-options"><button data-scene-mode="empty" aria-pressed="true">ฉากอย่างเดียว</button><button data-scene-mode="doll" aria-pressed="false">ลองกับตุ๊กตาของฉัน</button></div><button class="primary-button wide" data-select-product="${p.id}">เลือกฉากนี้</button><button class="text-button" data-back-shop>กลับไปร้าน</button></section>`);paintShopArt();dialog.scrollTop=0;}
 function renderManage(){
  const saved=records();shell('ของขวัญของฉัน',`<p class="cloud-intro">ไม่ต้องล็อกอิน ♡ รายการนี้เก็บไว้ในเบราว์เซอร์นี้<br>เก็บลิงก์จัดการส่วนตัวไว้เพื่อเปิดจากอุปกรณ์อื่น</p><div class="saved-gifts">${saved.length?saved.map(g=>`<article class="saved-gift"><div><span class="saved-gift-date">${date(g.createdAt)}</span><h3>${esc(g.title||'ความในใจของคุณ')}</h3><p>${esc(g.to?'ถึง '+g.to:'')}</p><small>${g.expiresAt?'เปิดได้ถึง '+date(g.expiresAt):'ตรวจสถานะการชำระก่อนส่ง'}</small></div><button class="secondary-button" data-manage-guest="${g.id}">เปิดจัดการ</button></article>`).join(''):'<p class="cloud-empty">ยังไม่มีของขวัญในอุปกรณ์นี้</p>'}</div><form id="guest-lookup"><label for="guest-lookup-link">มีลิงก์จัดการส่วนตัวอยู่แล้ว?</label><input id="guest-lookup-link" type="url" placeholder="วางลิงก์จัดการที่เก็บไว้" required><button class="secondary-button wide" type="submit">เปิดลิงก์จัดการ</button></form><p class="helper">คนที่มีลิงก์จัดการดูและถอนของขวัญได้ อย่าส่งลิงก์นี้ให้คนรับ<br>หากล้างข้อมูลเบราว์เซอร์แล้วไม่ได้เก็บลิงก์จัดการ จะกู้คืนรายการในอุปกรณ์ไม่ได้</p>`);
  dialog.querySelector('#guest-lookup').addEventListener('submit',e=>{e.preventDefault();try{const u=new URL(dialog.querySelector('#guest-lookup-link').value),q=new URLSearchParams(u.hash.slice(1)),id=q.get('id'),key=q.get('key');if(u.origin!==location.origin||u.pathname!=='/manage'||!validRecord(id,key))throw new Error();remember({id,manageToken:key});openGift(id);}catch{error('ตรวจลิงก์จัดการของเว็บนี้อีกครั้งนะ');}});
 }
 const validRecord=(id,key)=>/^[0-9a-f-]{36}$/i.test(id||'')&&/^[A-Za-z0-9_-]{43}$/.test(key||'');
 function editForm(g){return `<details class="guest-edit"><summary>แก้จดหมายและเพลง</summary><form id="guest-edit-form" data-id="${g.id}">${[['name','ชื่อตุ๊กตา',24],['from','ชื่อผู้ส่ง',24],['to','ชื่อผู้รับ',24],['title','หัวข้อจดหมาย',50],['message','ข้อความจดหมาย',100],['musicUrl','ลิงก์ YouTube / Spotify',2048],['songTitle','ชื่อเพลง',80]].map(([key,label,max])=>`<div class="field"><label for="guest-edit-${key}">${label}${key==='message'?' · ไม่เกิน 100 ตัวอักษร':''}</label>${key==='message'?`<textarea id="guest-edit-${key}" name="${key}" required>${esc(g.gift[key])}</textarea>`:`<input id="guest-edit-${key}" name="${key}" type="${key==='musicUrl'?'url':'text'}" value="${esc(g.gift[key])}" ${['from','to','title'].includes(key)?'required':''}>`}</div>`).join('')}<p class="helper">แก้ข้อความได้ก่อนลิงก์หมดอายุ ไม่ต่ออายุลิงก์ และไม่เปลี่ยนตุ๊กตา ดอกไม้ หรือฉากที่ซื้อ</p><button class="secondary-button wide" type="submit">บันทึกจดหมาย</button></form></details>`;}
 const statuses={free:'พร้อมส่ง · ฟรี 1 ชั่วโมง',pending:'รอชำระเงิน',paid:'ชำระแล้ว · พร้อมส่ง 30 วัน',expired:'หมดเวลาชำระเงิน',failed:'ชำระไม่สำเร็จ',refunded:'คืนเงินเต็มจำนวนแล้ว'};
 async function openGift(id,{quiet=false}={}){
  clearTimeout(poll);await ensureDialog();const row=records().find(r=>r.id===id);if(!row){renderManage();error('ไม่พบลิงก์จัดการในอุปกรณ์นี้ วางลิงก์ส่วนตัวที่คุณเก็บไว้ด้านล่างได้เลย');return;}
  if(!quiet)shell('กำลังเปิดความในใจ…','<p>กำลังตรวจของขวัญและการชำระเงิน</p>');if(!dialog.open)dialog.showModal();view='gift';
  try{const {gift:g}=await api('guest/manage',{method:'POST',body:{id,manageToken:row.manageToken}});remember({...row,status:g.status,expiresAt:g.expiresAt,createdAt:g.createdAt,title:g.gift?.title||row.title,to:g.gift?.to||row.to});
   const expired=!!g.expiresAt&&new Date(g.expiresAt)<=new Date(),pending=g.status==='pending'&&new Date(g.checkoutExpiresAt)>new Date();
   shell('ความในใจชิ้นนี้',`<div class="guest-status ${g.active?'is-active':''}">${esc(expired?'ลิงก์ของขวัญหมดอายุแล้ว':g.revoked?'ถอนลิงก์แล้ว':statuses[g.status]||'กำลังตรวจสอบ')}</div><h3>${esc(g.gift?.title||row.title||'ของขวัญของคุณ')}</h3><p class="helper">รหัสรายการ: <span class="guest-order-id">${esc(g.id)}</span>${g.expiresAt?'<br>เปิดได้ถึง '+date(g.expiresAt):'<br>30 วันเริ่มเมื่อยืนยันชำระสำเร็จ'}</p>${config.paymentMode==='test'&&g.amountMinor?'<p class="payment-test-note">โหมดทดสอบ · ไม่หักเงินจริง</p>':''}<div class="guest-lines">${g.items.map(p=>`<div><span>${esc(p.name)}</span><strong>${money(p)}</strong></div>`).join('')}<div class="guest-total"><span>ยอดรวม</span><strong>${money(g)}</strong></div></div>${g.active?copyField('ลิงก์สำหรับส่งให้คนรับ',g.recipientUrl,'recipient')+'<a class="primary-button wide guest-open-link" href="'+esc(g.recipientUrl)+'" target="_blank" rel="noopener noreferrer">เปิดของขวัญ</a>':''}${pending?'<p>ยอดเดียวสำหรับของขวัญนี้ รวมลิงก์ 30 วันแล้ว ไม่ปลดล็อกถาวรสำหรับชิ้นถัดไป</p><button class="primary-button wide" data-pay-guest="'+id+'">ไปชำระพร้อมเพย์ · '+money(g)+'</button><button class="secondary-button wide" data-manage-guest="'+id+'">ตรวจสถานะการชำระ</button><p class="helper">หากจ่ายแล้ว อย่าสแกน QR ซ้ำ ให้ตรวจสถานะก่อน</p>':''}${!g.payload?'<p class="helper">เนื้อหาของขวัญหมดระยะเก็บแล้ว เหลือเฉพาะข้อมูลอ้างอิงรายการ</p>':''}${!expired&&g.gift&&['free','paid'].includes(g.status)?editForm(g):''}${copyField('ลิงก์จัดการส่วนตัว — เก็บไว้กับคุณเท่านั้น',manageUrl(row),'manage')}<p class="guest-secret-note">ลิงก์นี้ใช้แทนบัญชีของคุณ เก็บไว้ก่อนปิดหน้าเว็บหรือเปลี่ยนอุปกรณ์</p>${!expired&&['free','paid'].includes(g.status)?'<button class="text-button" data-guest-action="'+(g.revoked?'restore':'revoke')+'" data-guest-id="'+id+'">'+(g.revoked?'เปิดลิงก์อีกครั้ง':'ถอนลิงก์ของขวัญ')+'</button>':''}<button class="secondary-button wide" data-back-manage>ของขวัญในอุปกรณ์นี้</button><p class="helper"><a href="/purchase-policy.html" target="_blank" rel="noopener">รายละเอียดการซื้อ</a> · <a href="/privacy.html" target="_blank" rel="noopener">ความเป็นส่วนตัว</a></p>`);
   if(pending)poll=setTimeout(()=>{if(dialog.open&&view==='gift')openGift(id,{quiet:true});},10000);
  }catch(e){error(e.message);}
 }
 async function pay(id,button){button.disabled=true;error('กำลังเปิดพร้อมเพย์…');try{const row=records().find(r=>r.id===id);if(!remember(row))throw new Error('เบราว์เซอร์เก็บข้อมูลไม่ได้ กรุณาคัดลอกลิงก์จัดการไว้ แล้วเปิดจากเบราว์เซอร์ที่อนุญาตจัดเก็บข้อมูล');const result=await api('guest/checkout',{method:'POST',body:{id,manageToken:row.manageToken}});if(result.checkoutUrl){const target=new URL(result.checkoutUrl);if(target.origin!=='https://checkout.stripe.com')throw new Error('ปลายทางชำระเงินไม่ถูกต้อง');location.assign(target.href);}else await openGift(id);}catch(e){error(e.message);button.disabled=false;}}
 async function ensureDialog(){if(dialog)return;dialog=document.createElement('dialog');dialog.id='cloud-dialog';dialog.className='cloud-dialog';dialog.setAttribute('aria-labelledby','cloud-title');document.body.append(dialog);dialog.addEventListener('submit',async e=>{if(e.target.id!=='guest-edit-form')return;e.preventDefault();const form=e.target,row=records().find(r=>r.id===form.dataset.id),button=e.submitter;button.disabled=true;try{const edit=Object.fromEntries([...form.querySelectorAll('[name]')].map(input=>[input.name,input.value]));await api('guest/manage',{method:'POST',body:{id:row.id,manageToken:row.manageToken,action:'edit',edit}});await openGift(row.id);error('บันทึกจดหมายแล้ว ♡');}catch(err){error(err.message);button.disabled=false;}});dialog.addEventListener('close',()=>clearTimeout(poll));dialog.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-cloud-close'))dialog.close();
  if(b.dataset.shopCategory){shopCategory=b.dataset.shopCategory;renderShop();}
  if(b.hasAttribute('data-back-shop'))renderShop();
  if(b.dataset.previewScene)previewScene(b.dataset.previewScene);
  if(b.dataset.sceneMode){const show=b.dataset.sceneMode==='doll';dialog.querySelector('[data-scene-doll]').classList.toggle('hidden',!show);dialog.querySelectorAll('[data-scene-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}
  if(b.dataset.selectProduct){const p=(config.products||window.LoveCatalog.products).find(p=>p.id===b.dataset.selectProduct);if(p){window.dispatchEvent(new CustomEvent('cloud-select',{detail:p}));dialog.close();}}
  if(b.hasAttribute('data-back-manage')){view='manage';clearTimeout(poll);renderManage();}
  if(b.dataset.manageGuest)await openGift(b.dataset.manageGuest);
  if(b.dataset.payGuest)await pay(b.dataset.payGuest,b);
  if(b.dataset.guestAction){b.disabled=true;try{const row=records().find(r=>r.id===b.dataset.guestId);await api('guest/manage',{method:'POST',body:{id:row.id,manageToken:row.manageToken,action:b.dataset.guestAction}});await openGift(row.id);}catch(e){error(e.message);b.disabled=false;}}
  if(b.dataset.guestCopy){const input=dialog.querySelector('#guest-'+b.dataset.guestCopy);try{await navigator.clipboard.writeText(input.value);error('คัดลอกแล้ว ♡');}catch{input.focus();input.select();error('เลือกลิงก์แล้ว กดคัดลอกในอุปกรณ์ได้เลย');}}
 });}
 async function open(target='manage',unused,category){await ready;await ensureDialog();clearTimeout(poll);view=target;if(category)shopCategory=category;if(target==='shop')renderShop();else renderManage();if(!dialog.open)dialog.showModal();}
 async function createGift(gift,plan='hour'){
  await ready;if(!config.configured||!config.guestMode)throw new Error('กำลังอัปเดตระบบส่งแบบไม่ล็อกอิน กรุณาลองอีกครั้งในอีกสักครู่');
  const fingerprint=JSON.stringify({gift,plan});let pending;try{pending=JSON.parse(localStorage.getItem(pendingKey));}catch{}
  if(!pending||pending.fingerprint!==fingerprint){const bytes=crypto.getRandomValues(new Uint8Array(32));pending={requestId:crypto.randomUUID(),manageToken:btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''),fingerprint};try{localStorage.setItem(pendingKey,JSON.stringify(pending));}catch{throw new Error('ต้องอนุญาตให้เบราว์เซอร์เก็บแบบร่างก่อนสร้างลิงก์ เพื่อกลับมาจัดการหรือรับของขวัญหลังชำระเงินได้');}}
  const {gift:g}=await api('guest/create',{method:'POST',body:{gift,plan,requestId:pending.requestId,manageToken:pending.manageToken}});
  const row={id:g.id,manageToken:pending.manageToken,title:gift.title,to:gift.to,status:g.status,createdAt:g.createdAt,expiresAt:g.expiresAt};remember(row);
  if(g.status==='pending'){await openGift(g.id);return {pending:true,id:g.id};}
  if(!g.active)throw new Error('ลิงก์นี้หมดอายุหรือถูกถอนแล้ว เริ่มของขวัญชิ้นใหม่เพื่อสร้างลิงก์ใหม่');
  return {...g,manageUrl:manageUrl(row)};
 }
 window.LoveCloud={ready,api,has,open,openGift,createGift,clearPending:()=>{try{localStorage.removeItem(pendingKey);}catch{}},refresh:async()=>{},get user(){return null;},get config(){return config;}};
 document.addEventListener('click',e=>{if(e.target.closest('#open-manage'))open('manage');if(e.target.closest('#open-shop'))open('shop');});
 ready.then(async()=>{if(location.pathname!=='/manage')return;const q=new URLSearchParams(location.hash.slice(1)),id=q.get('id'),key=q.get('key');if(validRecord(id,key)){remember({id,manageToken:key});await openGift(id);return;}const returned=new URLSearchParams(location.search).get('gift');if(returned){await openGift(returned);history.replaceState(null,'','/manage');}else await open();});
})();
